def count_hexagons(L):
    def H(n):
        if n < 0:
            return 0
        return 3*n**2 + 3*n + 1

    total = 0
    for M in range(1, L + 1):
        # f(M) is the number of vectors (a, b, c) such that a+b+c=0 and max(|a|,|b|,|c|) = M
        # g(M) is the number of vectors (a, b, c) such that a+b+c=0 and max(|a|,|b|,|c|) <= M
        # g(M) = H(M)
        f_M = H(M) - H(M-1)
        total += (f_M / 6.0) * H(L - M)
    return int(round(total))

for L in range(1, 11):
    print(f"L={L}: {count_hexagons(L)}")
